1	import Phaser from 'phaser';
2	import { BaseAbility } from './BaseAbility';
3	import type { GameSceneAPI } from './types';
4	import type PoolablePoopBase from '../objects/PoolablePoopBase';
5	import { MUGI_PARAMS } from '../config/abilityParams';
6	import { ensureGlowDot } from '../utils/glowDot';
7	
8	// 옆면 연꽃 꽃잎 정의: [rotDeg, width, height, color, depthOffset]
9	// 꽃잎 바닥이 한 점에 모이고 각도 방향으로 뻗어나가는 형태
10	const LOTUS_DEFS: [number, number, number, number, number][] = [
11	  [ -68, 11, 30, 0xfff8e1, 0 ],
12	  [  68, 11, 30, 0xfff8e1, 0 ],
13	  [ -46, 10, 27, 0xfffde7, 1 ],
14	  [  46, 10, 27, 0xfffde7, 1 ],
15	  [ -26,  9, 24, 0xffffff, 2 ],
16	  [  26,  9, 24, 0xffffff, 2 ],
17	  [ -10,  8, 21, 0xffffff, 3 ],
18	  [  10,  8, 21, 0xffffff, 3 ],
19	  [   0,  7, 18, 0xffffff, 4 ],
20	];
21	
22	interface YeoijuOrb {
23	  gfx: Phaser.GameObjects.Graphics;
24	  x: number;
25	  y: number;
26	}
27	
28	interface OrbitOrb {
29	  gfx: Phaser.GameObjects.Graphics;
30	  angle: number;
31	  speed: number;    // rad/ms (음수 = 반시계)
32	  radius: number;
33	  tiltCos: number;  // 궤도 기울기 (작을수록 납작한 타원)
34	}
35	
36	const HALO_Y_OFFSET = 28; // 후광 중심을 플레이어 중심보다 위로
37	
38	// 각 궤도 고유 파라미터 — 전자 궤도처럼 방향/기울기/속도 다양화
39	const ORBIT_CONFIGS: { speed: number; radius: number; tiltCos: number; startAngle: number }[] = [
40	  {  speed:  0.0050, radius: 30, tiltCos: 0.32, startAngle: 0 },
41	  {  speed: -0.0043, radius: 32, tiltCos: 0.58, startAngle: Math.PI * 0.7 },
42	  {  speed:  0.0060, radius: 29, tiltCos: 0.44, startAngle: Math.PI * 1.3 },
43	  {  speed: -0.0038, radius: 34, tiltCos: 0.22, startAngle: Math.PI * 0.4 },
44	  {  speed:  0.0048, radius: 31, tiltCos: 0.78, startAngle: Math.PI * 1.7 },
45	];
46	
47	export class MugiAbility extends BaseAbility {
48	  private lastYeoijuScore    = 0;
49	  private yeoijuCount        = 0;
50	  private yeoijus: YeoijuOrb[] = [];
51	  private orbitOrbs: OrbitOrb[] = [];
52	  private normalPrefix     = 'mugi_';
53	  private isGoldForm       = false;
54	  private auraTimer        = 0;
55	  private revivalHaloOuter: Phaser.GameObjects.Image | null = null;
56	  private revivalHaloInner: Phaser.GameObjects.Image | null = null;
57	
58	  // Revival state
59	  private revivalCharges     = 1;   // 0 or 1 (max stored)
60	  private totalRevivalsUsed  = 0;   // lifetime cap: 3
61	  private revivalChargeCount = 0;   // yeoijus collected toward recharge
62	
63	  override onCreate(api: GameSceneAPI): void {
64	    this.lastYeoijuScore    = 0;
65	    this.yeoijuCount        = 0;
66	    this.yeoijus            = [];
67	    this.orbitOrbs          = [];
68	    this.normalPrefix       = api.player.getTexturePrefix();
69	    this.isGoldForm         = false;
70	    this.auraTimer          = 0;
71	    this.revivalHaloOuter   = null;
72	    this.revivalHaloInner   = null;
73	    this.revivalCharges     = 1;
74	    this.totalRevivalsUsed  = 0;
75	    this.revivalChargeCount = 0;
76	    ensureGlowDot(api.scene);
77	    this._createRevivalHalo(api);
78	  }
79	
80	  override onScoreMilestone(score: number, api: GameSceneAPI): void {
81	    const interval = this.isGoldForm ? MUGI_PARAMS.yeoijuGoldInterval : MUGI_PARAMS.yeoijuInterval;
82	    if (score % interval === 0 && score > this.lastYeoijuScore) {
83	      this.lastYeoijuScore = score;
84	      this._spawnYeoiju(api);
85	    }
86	  }
87	
88	  override onUpdate(api: GameSceneAPI): void {
89	    this._updateYeoijus(api);
90	    this._tickAura(api);
91	    this._updateOrbitOrbs(api);
92	    this._updateRevivalHalo(api.player.x, api.player.y);
93	  }
94	
95	  override onHitPoop(api: GameSceneAPI): boolean {
96	    if (this.revivalCharges > 0 && this.totalRevivalsUsed < 3) {
97	      this._revive(api);
98	      return true;
99	    }
100	    return false;
101	  }
102	
103	  // ── 여의주 ──────────────────────────────────────────────────────────
104	
105	  private _spawnYeoiju(api: GameSceneAPI): void {
106	    const scene = api.scene;
107	    const x = Phaser.Math.Between(30, 370);
108	
109	    const gfx = scene.add.graphics().setDepth(150);
110	    // 구체 본체 (짙은 검붉)
111	    gfx.fillStyle(0x550000, 1);    gfx.fillCircle(0, 0, 11);
112	    // 내부 광원 — 중앙 살짝 아래 오프셋 (속에서 빛나는 느낌)
113	    gfx.fillStyle(0xaa1100, 0.95); gfx.fillCircle(1, 2, 8);
114	    gfx.fillStyle(0xdd2200, 0.80); gfx.fillCircle(1, 2, 5);
115	    gfx.fillStyle(0xff5500, 0.55); gfx.fillCircle(1, 3, 2.5);
116	    // 반사 하이라이트 — 왼쪽 위 (구슬 3D 효과)
117	    gfx.fillStyle(0xffffff, 0.90); gfx.fillCircle(-3.5, -3.5, 2.5);
118	    gfx.fillStyle(0xffffff, 0.40); gfx.fillCircle(-2.5, -5, 1);
119	    gfx.setPosition(x, -20);
120	
121	    scene.tweens.add({
122	      targets: gfx, alpha: { from: 0.72, to: 1 },
123	      yoyo: true, repeat: -1, duration: 720, ease: 'Sine.easeInOut',
124	    });
125	
126	    this.yeoijus.push({ gfx, x, y: -20 });
127	  }
128	
129	  private _updateYeoijus(api: GameSceneAPI): void {
130	    const delta = api.scene.game.loop.delta * 0.001;
131	    const { player } = api;
132	    const fallDelta = (api.baseSpeed + api.difficultyLevel * 40) * delta;
133	    const r2 = MUGI_PARAMS.yeoijuCollectRadius ** 2;
134	    const remaining: YeoijuOrb[] = [];
135	
136	    for (const orb of this.yeoijus) {
137	      orb.y += fallDelta;
138	      orb.gfx.setPosition(orb.x, orb.y);
139	
140	      const dx = player.x - orb.x;
141	      const dy = player.y - orb.y;
142	      if (dx * dx + dy * dy < r2) {
143	        this._collectYeoiju(orb, api);
144	        continue;
145	      }
146	      if (orb.y > 660) { orb.gfx.destroy(); continue; }
147	      remaining.push(orb);
148	    }
149	    this.yeoijus = remaining;
150	  }
151	
152	  private _collectYeoiju(orb: YeoijuOrb, api: GameSceneAPI): void {
153	    this._spawnCollectEffect(orb.x, orb.y, api.scene);
154	    orb.gfx.destroy();
155	    api.addAbilityBonus(80);
156	
157	    // Revival recharge: runs regardless of gold form
158	    if (this.revivalCharges === 0 && this.totalRevivalsUsed < 3) {
159	      this.revivalChargeCount++;
160	      if (this.revivalChargeCount >= MUGI_PARAMS.goldThreshold) {
161	        this.revivalCharges = 1;
162	        this.revivalChargeCount = 0;
163	        this._playRechargeGlow(api);
164	      }
165	    }
166	
167	    if (this.isGoldForm) {
168	      this._strikeThunder(api, false);
169	      return;
170	    }
171	
172	    this.yeoijuCount++;
173	
174	    if (this.yeoijuCount % 10 === 0 && this.orbitOrbs.length < 5) {
175	      this._spawnOrbitOrb(api);
176	    }
177	
178	    if (this.yeoijuCount >= MUGI_PARAMS.goldThreshold) {
179	      this._transformGold(api);
180	    } else {
181	      this._strikeRedLightning(api);
182	    }
183	  }
184	
185	  // ── 기운 (아우라) 이펙트 ─────────────────────────────────────────────
186	
187	  private _tickAura(api: GameSceneAPI): void {
188	    const level = this.isGoldForm ? 4 : Math.floor(this.yeoijuCount / 10);
189	    const delta = api.scene.game.loop.delta;
190	
191	    // 레벨별 검은/금색 기운
192	    if (level > 0) {
193	      this.auraTimer += delta;
194	      const interval = Math.max(70, 400 - level * 70);
195	      if (this.auraTimer >= interval) {
196	        this.auraTimer -= interval;
