448	  private _clearPoops(
449	    api: GameSceneAPI,
450	    filter: (p: Phaser.Physics.Arcade.Sprite) => boolean,
451	    pointsPerPoop: number,
452	  ): void {
453	    const { poops, scene } = api;
454	    const targets = (poops.getChildren() as Phaser.Physics.Arcade.Sprite[])
455	      .filter(p => p.active && filter(p));
456	
457	    if (targets.length === 0) return;
458	
459	    // 위치를 먼저 저장한 뒤 즉시 재활용 — 피버 타임이 얼어있는 똥을
460	    // 특수 똥으로 변환하는 race condition을 원천 차단
461	    const positions = targets.map(p => ({ x: p.x, y: p.y }));
462	    targets.forEach(p => (p as unknown as PoolablePoopBase).recycle());
463	
464	    // 잽 이펙트는 저장된 위치에서 독립적으로 재생
465	    positions.forEach(({ x, y }) => this._spawnZapEffect(x, y, scene));
466	
467	    scene.time.delayedCall(450, () => {
468	      if (!scene.sys.isActive()) return;
469	      api.addAbilityBonus(positions.length * pointsPerPoop);
470	    });
471	  }
