473	  private _makeBoltPts(tx: number, ty: number, startX: number): { x: number; y: number }[] {
474	    const pts: { x: number; y: number }[] = [{ x: startX, y: -10 }];
475	    for (let i = 1; i < 17; i++) {
476	      const t = i / 17;
477	      const spread = 70 * (1 - t * 0.65);
478	      pts.push({ x: tx + Phaser.Math.Between(-spread, spread), y: (ty + 20) * t - 10 });
479	    }
480	    pts.push({ x: tx, y: ty + 8 });
481	    return pts;
482	  }
