484	  private _drawPolyline(g: Phaser.GameObjects.Graphics, pts: { x: number; y: number }[]): void {
485	    g.beginPath();
486	    g.moveTo(pts[0]!.x, pts[0]!.y);
487	    for (let i = 1; i < pts.length; i++) g.lineTo(pts[i]!.x, pts[i]!.y);
488	    g.strokePath();
489	  }
