498	        const color = Math.random() < 0.55 ? 0xffee00 : 0xffffff;
499	        g.lineStyle(Phaser.Math.FloatBetween(1.5, 2.5), color, 1);
500	        g.beginPath();
501	        let px = x + Phaser.Math.Between(-7, 7);
502	        let py = y + Phaser.Math.Between(-7, 7);
503	        g.moveTo(px, py);
504	        for (let j = 0; j < 3; j++) {
505	          px += Phaser.Math.Between(-10, 10);
506	          py += Phaser.Math.Between(-10, 10);
507	          g.lineTo(px, py);
