550	  private _playRevivalLotus(px: number, py: number, scene: Phaser.Scene): void {
551	    const LS = 2.2;                // 연꽃 전체 스케일
552	    const cx = px;
553	    const cy = py + 38;            // 플레이어 발 바닥 (displayH=80 → 중심 +40, base offset -2)
554	
555	    // 꽃받침
556	    const base = scene.add.graphics().setDepth(352).setScale(0);
557	    base.fillStyle(0x66bb6a, 0.85); base.fillEllipse(0, 0, 28 * LS, 9 * LS);
558	    base.fillStyle(0x81c784, 0.6);  base.fillEllipse(0, -2 * LS, 16 * LS, 5 * LS);
559	    base.setPosition(cx, cy + 2);
560	    scene.tweens.add({ targets: base, scale: 1, duration: 220, ease: 'Back.easeOut' });
561	
562	    // 금빛 중앙 글로우
563	    const glow = scene.add.graphics().setDepth(353).setScale(0);
564	    glow.fillStyle(0xffd700, 0.20); glow.fillCircle(0, 0, 30 * LS);
565	    glow.fillStyle(0xffe082, 0.35); glow.fillCircle(0, 0, 18 * LS);
566	    glow.fillStyle(0xffffff, 0.55); glow.fillCircle(0, 0,  8 * LS);
567	    glow.setPosition(cx, cy - 14 * LS);
568	    scene.tweens.add({ targets: glow, scale: 1, duration: 320, ease: 'Back.easeOut' });
569	
570	    // sin(t*π) 곡선으로 양 끝 뾰족한 꽃잎 폴리곤
571	    const petalPts = (w: number, h: number): { x: number; y: number }[] => {
572	      const N = 16;
573	      const pts: { x: number; y: number }[] = [];
574	      for (let i = 0; i <= N; i++) {
575	        const t = i / N;
576	        pts.push({ x:  (w / 2) * Math.sin(t * Math.PI), y: h / 2 - t * h });
577	      }
578	      for (let i = N - 1; i >= 0; i--) {
579	        const t = i / N;
580	        pts.push({ x: -(w / 2) * Math.sin(t * Math.PI), y: h / 2 - t * h });
581	      }
582	      return pts;
583	    };
584	
585	    // 꽃잎: 바닥 한 점에서 각도 방향으로 뻗어나가는 옆면 형태
586	    const petalGfxs: Phaser.GameObjects.Graphics[] = [];
587	    LOTUS_DEFS.forEach(([rotDeg, w, h, color, depthOff], idx) => {
588	      const sw = w * LS;
589	      const sh = h * LS;
590	      const rotRad = rotDeg * Math.PI / 180;
591	      const ppx = cx + Math.sin(rotRad) * (sh / 2);
592	      const ppy = (cy + 2) - Math.cos(rotRad) * (sh / 2);
593	
594	      const g = scene.add.graphics().setDepth(353 + depthOff);
595	      g.fillStyle(color, 0.92);
596	      g.fillPoints(petalPts(sw, sh), true);
597	      g.fillStyle(0xffffff, 0.45);
598	      g.fillPoints(petalPts(sw * 0.35, sh * 0.65), true);
599	      g.fillStyle(0xffd700, 0.18);
600	      g.fillEllipse(0, -(sh * 0.3), sw * 0.55, sh * 0.22);
601	      g.setPosition(ppx, ppy).setRotation(rotRad).setScale(0);
602	
603	      scene.tweens.add({ targets: g, scale: 1, delay: idx * 40, duration: 280, ease: 'Back.easeOut' });
604	      petalGfxs.push(g);
605	    });
606	
607	    // 수술
608	    const stamen = scene.add.graphics().setDepth(359).setScale(0);
609	    stamen.fillStyle(0xffd700, 1); stamen.fillCircle(0, 0, 5 * LS);
610	    stamen.fillStyle(0xffff99, 0.9); stamen.fillCircle(0, 0, 3 * LS);
611	    stamen.fillStyle(0xffffff, 0.7); stamen.fillCircle(-1 * LS, -1.5 * LS, 1.5 * LS);
612	    stamen.setPosition(cx, cy - 20 * LS);
613	    scene.tweens.add({
614	      targets: stamen, scale: 1,
615	      delay: LOTUS_DEFS.length * 40 - 20, duration: 220, ease: 'Back.easeOut',
616	    });
617	
618	    // 900ms 후 조용히 페이드아웃
619	    const allObjs: Phaser.GameObjects.Graphics[] = [...petalGfxs, glow, base, stamen];
620	    scene.time.delayedCall(900, () => {
621	      if (!scene.sys.isActive()) return;
622	      allObjs.forEach(obj => {
623	        scene.tweens.add({
624	          targets: obj, alpha: 0,
625	          duration: 500, ease: 'Quad.easeIn',
626	          onComplete: () => { if (obj.active) obj.destroy(); },
627	        });
628	      });
629	    });
630	  }
